            }
            catch (IOException e)
            {
                throw new IllegalStateException("malformed object: " + e);
            }
        }
        this.octets = bOut.toByteArray();
    }

private int getLengthOfLength(byte[] data)
    {
        int count = 2;               // TODO: assumes only a 1 byte tag number

        while((data[count - 1] & 0x80) != 0)
        {
            count++;
        }

        return count;
    }

