public OIDTokenizer(
        String oid)
    {
        this.oid = oid;
        this.index = 0;
    }

public boolean hasMoreTokens()
    {
        return (index != -1);
    }

public String nextToken()
    {
        if (index == -1)
        {
            return null;
        }

        String  token;
        int     end = oid.indexOf('.', index);

        if (end == -1)
        {
            token = oid.substring(index);
            index = -1;
            return token;
        }

        token = oid.substring(index, end);

        index = end + 1;
        return token;
    }

