      ContentValues contentValues = new ContentValues();
      contentValues.put(Data.RAW_CONTACT_ID, rawContactId);
      contentValues.put(Data.MIMETYPE, Im.CONTENT_ITEM_TYPE);
      contentValues.put(Im.PROTOCOL, Im.PROTOCOL_CUSTOM);
