      throw new AssertionError(ike);
    }
  }

public SessionKey(int localKeyId, int remoteKeyId, SecretKeySpec cipherKey, SecretKeySpec macKey, MasterSecret masterSecret) {
    this.localKeyId   = localKeyId;
