      return Integer.parseInt(port);
    }

private static byte[] makeRequest(Context context, MmsConnectionParameters connectionParameters, String url)
      throws IOException
  {
    AndroidHttpClient client = null;

    try {
      client            = constructHttpClient(context, connectionParameters);
      URI targetUrl     = new URI(url.trim());
      HttpHost target   = new HttpHost(targetUrl.getHost(), targetUrl.getPort(), HttpHost.DEFAULT_SCHEME_NAME);
      HttpGet request   = new HttpGet(url.trim());

      request.setParams(client.getParams());
      request.addHeader("Accept", "*/*, application/vnd.wap.mms-message, application/vnd.wap.sic");

      HttpResponse response = client.execute(target, request);
      StatusLine status     = response.getStatusLine();

      if (status.getStatusCode() != 200)
        throw new IOException("Non-successful HTTP response: " + status.getReasonPhrase());

      return parseResponse(response.getEntity());
    } catch (URISyntaxException use) {
      Log.w("MmsDownloadHelper", use);
      throw new IOException("Couldn't parse URI");
    } finally {
      if (client != null)
        client.close();
    }
  }

public static boolean isMmsConnectionParametersAvailable(Context context, String apn, boolean proxyIfPossible) {
    try {
      getMmsConnectionParameters(context, apn, proxyIfPossible);
      return true;
    } catch (ApnUnavailableException e) {
      return false;
    }
  }

public static RetrieveConf retrieveMms(Context context, String url, String apn,
                                         boolean usingMmsRadio, boolean proxyIfPossible)
      throws IOException, ApnUnavailableException
  {
    MmsConnectionParameters connectionParameters = getMmsConnectionParameters(context, apn, proxyIfPossible);

    checkRouteToHost(context, connectionParameters, url, usingMmsRadio);

    byte[] pdu = makeRequest(context, connectionParameters, url);

    if (pdu == null) {
      throw new IOException("Retrieved null PDU!");
    }

    RetrieveConf retrieved = (RetrieveConf)new PduParser(pdu).parse();

    if (retrieved == null) {
      throw new IOException("Bad retrieved PDU");
    }

    return retrieved;
  }

private static byte[] makePost(Context context, MmsConnectionParameters parameters, byte[] mms) throws ClientProtocolException, IOException {
    AndroidHttpClient client = null;

    try {
      Log.w("MmsSender", "Sending MMS1 of length: " + (mms != null ? mms.length : "null"));
      client                 = constructHttpClient(context, parameters);
      URI targetUrl          = new URI(parameters.getMmsc());

      if (Util.isEmpty(targetUrl.getHost()))
        throw new IOException("Invalid target host: " + targetUrl.getHost() + " , " + targetUrl);

      HttpHost target        = new HttpHost(targetUrl.getHost(), targetUrl.getPort(), HttpHost.DEFAULT_SCHEME_NAME);
      HttpPost request       = new HttpPost(parameters.getMmsc());
      ByteArrayEntity entity = new ByteArrayEntity(mms);

      entity.setContentType("application/vnd.wap.mms-message");

      request.setEntity(entity);
      request.setParams(client.getParams());
      request.addHeader("Accept", "*/*, application/vnd.wap.mms-message, application/vnd.wap.sic");
      request.addHeader("x-wap-profile", "http://www.google.com/oha/rdf/ua-profile-kila.xml");
      HttpResponse response = client.execute(target, request);
      StatusLine status     = response.getStatusLine();

      if (status.getStatusCode() != 200)
        throw new IOException("Non-successful HTTP response: " + status.getReasonPhrase());

      return parseResponse(response.getEntity());
    } catch (URISyntaxException use) {
      Log.w("MmsSendHelper", use);
      throw new IOException("Couldn't parse URI.");
    } finally {
      if (client != null)
        client.close();
    }
  }

public static void sendNotificationReceived(Context context, byte[] mms, String apn,
                                              boolean usingMmsRadio, boolean useProxyIfAvailable)
